catalog_script_client.script:
var validations = {};

validations.Validation_Basic = ( function() {
	"use strict";

	function _validate() {
		console.info( "x_gamlp_idm_lc.On Submit Validation.validations.Validation_Basic._validate()" );
		var result = [];
//		if ( g_form.getValue( "running_from" ) != "order_guide" ) {
			var requestedOfferings = g_form.getValue( "requested_offering" ).toString().split( "," ).sort();
			var initialOfferings = g_form.getValue( "initial_offering" ).toString().split( "," ).sort();

			if ( requestedOfferings.join( "," ) == initialOfferings.join( "," ) ) {
				if ( g_form.getValue( "running_from" ) == "order_guide" ) {
					result.push( "x_gamlp_idm_lc.form.ERROR.Validation.NoChangesDetectedOrderGuide" );
				} else {
					result.push( "x_gamlp_idm_lc.form.ERROR.Validation.NoChangesDetected" );
				}
			}
//		}

		console.info( "x_gamlp_idm_lc.On Submit Validation.validations.Validation_Basic._validate() result=" + result.join( "," ) );
		return result;
	}

	return {
		validate: function() {
			console.info( "x_gamlp_idm_lc.On Submit Validation.validations.Validation_Basic.validate()" );
			return _validate();
		},
	};

} );

validations.Validation_SingleOfferingSelectionPerEnvironment = ( function() {
	"use strict";

	var _basicValidation = validations.Validation_Basic();

	function _validate() {
		console.info( "x_gamlp_idm_lc.On Submit Validation.validations.Validation_SingleOfferingSelectionPerEnvironment._validate()" );
		var result = [];
		var businessService = JSON.parse( g_form.getValue( "business_service_config" ) );

		var selectedOfferings = g_form.getValue( "requested_offering" );
		var selectedPlatforms = businessService.getOfferings.filter( function( offering ) {
				return selectedOfferings.indexOf( offering.sys_id.value.toString() ) != -1;
			}, this )
			.map( function( offering ) {
				return offering.used_for.value.toString();
			}, this );

		var uniqueSelectedPlatforms = selectedPlatforms.filter( function( item, pos ) {
				return selectedPlatforms.indexOf( item ) == pos; 
			}, this );

		if ( uniqueSelectedPlatforms.length != selectedPlatforms.length ) {
			result.push( "x_gamlp_idm_lc.form.ERROR.Validation.SingleOfferingSelectionPerEnvironment" );
		}

		result = result.concat( _basicValidation.validate() );

		console.info( "x_gamlp_idm_lc.On Submit Validation.validations.Validation_SingleOfferingSelectionPerEnvironment._validate() result=" + result.join( "," ) );
		return result;
	}

	return {
		validate: function() {
			console.info( "x_gamlp_idm_lc.On Submit Validation.validations.Validation_SingleOfferingSelectionPerEnvironment._validate()" );
			return _validate();
		},
	};

} );

validations.ValidationManager = ( function() {
	"use strict";

	var _validation;
	var _validationType;

	function _validate( validationType ) {
		console.info( "x_gamlp_idm_lc.ValidationManager._validate()" );

		if ( typeof _validationType === "undefined" || _validationType != validationType ) {
			_validationType = validationType;
			_validation = validations[ "Validation_" + _validationType ]();
		}

		return _validation.validate();
	}

	return {
		validate: function( validationType ) {
			console.info( "x_gamlp_idm_lc.ValidationManager.validate()" );
			return _validate( validationType );
		},
	};

} );


function onSubmit() {
	console.info( "x_gamlp_idm_lc.Validation.onSubmit()" );

	g_form.addInfoMessage( getMessage( "x_gamlp_idm_lc.form.ValidationInProgress" ) );
	var validation = validations.ValidationManager();
	var messages = validation.validate( g_form.getValue( "validation" ) );
//	g_form.clearAllFormMessages();
	g_form.clearMessages();

	messages.forEach( function( message ) {
		g_form.addErrorMessage( getMessage( message ) );
	}, this );

	if ( messages.length != 0 ) {
		g_form.addErrorMessage( getMessage( "x_gamlp_idm_lc.form.ERROR.FixError" ) );
	}

	return messages.length == 0;
}
